From dc017a02deb17b1adec9a977470482742bf54a9e Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 00:37:28 +0100
Subject: [PATCH] trianglemousefilter: hold the previous item's hover leave
 with the enter

The filter held back the next item's hover enter but let the old item's
hover leave through, so the old task tooltip closed before the new one
could reuse it. Hold that leave too and send it just before the enter.

BUG: 513390
---
 .../trianglemousefilter.cpp                   | 25 +++++++++++++++++++
 .../trianglemousefilter/trianglemousefilter.h |  2 ++
 2 files changed, 27 insertions(+)

diff --git a/components/trianglemousefilter/trianglemousefilter.cpp b/components/trianglemousefilter/trianglemousefilter.cpp
index fcc9db33fc..cf37d961d8 100644
--- a/components/trianglemousefilter/trianglemousefilter.cpp
+++ b/components/trianglemousefilter/trianglemousefilter.cpp
@@ -27,6 +27,7 @@ TriangleMouseFilter::TriangleMouseFilter(QQuickItem *parent)
         if (m_interceptedHoverItem) {
             resendHoverEvents(m_interceptedHoverItem.interceptedHoverEnterPosition.value());
         }
+        sendHeldHoverLeaves();

         m_interceptionPos.reset();
     });
@@ -35,6 +36,7 @@ TriangleMouseFilter::TriangleMouseFilter(QQuickItem *parent)
 bool TriangleMouseFilter::childMouseEventFilter(QQuickItem *item, QEvent *event)
 {
     if (!m_active) {
+        sendHeldHoverLeaves();
         // Even if inactive, we still need to record the current item so when active becomes true after the child item is hovered, the filter can still work
         // correctly
         switch (event->type()) {
@@ -54,6 +56,12 @@ bool TriangleMouseFilter::childMouseEventFilter(QQuickItem *item, QEvent *event)
     case QEvent::HoverLeave:
         if (m_interceptedHoverItem == item) {
             m_interceptedHoverItem = nullptr;
+            sendHeldHoverLeaves();
+        } else if (m_interceptedHoverItem) {
+            // Keep the previous item hovered until the intercepted item gets its hover enter,
+            // so e.g. its tooltip stays open for the new item to take over
+            m_heldHoverLeaves.append({item, static_cast<QHoverEvent *>(event)->position()});
+            return true;
         }
         return false;
     case QEvent::HoverEnter:
@@ -132,6 +140,10 @@ bool TriangleMouseFilter::childMouseEventFilter(QQuickItem *item, QEvent *event)
             // Pass event through
             m_interceptionPos = position;

+            if (he.type() == QEvent::HoverEnter) {
+                sendHeldHoverLeaves();
+            }
+
             if (he.type() == QEvent::HoverMove && m_interceptedHoverItem == item) {
                 resendHoverEvents(position);
             }
@@ -145,6 +157,8 @@ bool TriangleMouseFilter::childMouseEventFilter(QQuickItem *item, QEvent *event)

 void TriangleMouseFilter::resendHoverEvents(const QPointF &cursorPosition)
 {
+    sendHeldHoverLeaves();
+
     // If we are no longer inhibiting events and have previously intercepted a hover enter
     // we manually send the hover enter to that item
     if (m_interceptionPos) {
@@ -162,6 +176,17 @@ void TriangleMouseFilter::resendHoverEvents(const QPointF &cursorPosition)
     m_interceptedHoverItem = nullptr;
 }

+void TriangleMouseFilter::sendHeldHoverLeaves()
+{
+    const auto heldHoverLeaves = std::exchange(m_heldHoverLeaves, {});
+    for (const auto &[item, position] : heldHoverLeaves) {
+        if (item) {
+            QHoverEvent e(QEvent::HoverLeave, position, position);
+            qApp->sendEvent(item, &e);
+        }
+    }
+}
+
 bool TriangleMouseFilter::filterContains(const QPointF &p) const
 {
     if (!m_interceptionPos) {
diff --git a/components/trianglemousefilter/trianglemousefilter.h b/components/trianglemousefilter/trianglemousefilter.h
index 64748cdaa5..88c256f527 100644
--- a/components/trianglemousefilter/trianglemousefilter.h
+++ b/components/trianglemousefilter/trianglemousefilter.h
@@ -114,10 +114,12 @@ private:

     bool filterContains(const QPointF &p) const;
     void resendHoverEvents(const QPointF &cursorPosition);
+    void sendHeldHoverLeaves();

     QTimer m_resetTimer;

     InterceptedQuickItemData m_interceptedHoverItem; // item newly entered but the enter event was intercepted
+    QList<std::pair<QPointer<QQuickItem>, QPointF>> m_heldHoverLeaves; // hover leaves held back while an enter is intercepted

     std::optional<QPointF> m_lastCursorPosition;
     std::optional<decltype(std::declval<QHoverEvent>().timestamp())> m_lastTimestamp;
